const ADMIN = 'https://vip-realty.netlify.app/admin';
const sd = $getWorkflowStaticData('global');
sd.sent = sd.sent || {};
const now = Date.now();
for (const k of Object.keys(sd.sent)) if (now - sd.sent[k] > 6 * 3600 * 1000) delete sd.sent[k];
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const out = [];
for (const it of $input.all()) {
  const e = it.json || {};
  const wf = e.workflow?.name || '?';
  const node = e.execution?.lastNodeExecuted || e.execution?.error?.node?.name || '?';
  const msg = String(e.execution?.error?.message || e.trigger?.error?.message || 'unknown error');
  const url = e.execution?.url;
  let text, key;
  const notValid = msg.match(/^Extraction was not valid \(status: ([^)]*)\)/);
  if (notValid) {
    key = 'nv|' + (e.execution?.id || now);
    text = '📝 <b>Հայտարարությունը չմշակվեց</b>\n\nAI-ը կարդաց WhatsApp-ի հաղորդագրությունը, բայց տվյալները թերի են (' + esc(notValid[1]) + ')։ Telegram քարտ չի ստեղծվել։\n\nԽնդրեք գործակալին նորից ուղարկել ամբողջական տեքստով՝ գործարքի տեսակ, գույքի տեսակ, գին, քաղաք/թաղամաս։\n\n<a href="' + ADMIN + '/pipeline">Մանրամասներ ադմինում</a>';
  } else if (/extraction failed/i.test(msg) || /Gemini/i.test(msg)) {
    key = 'ai';
    text = '🤖 <b>AI-ը չկարողացավ մշակել հայտարարությունը</b>\n\nGemini-ն անհասանելի էր կամ սխալ պատասխանեց (փորձվել են 3 մոդել)։ Եթե կրկնվում է, ստուգեք Gemini API key-ը և հաշվի վճարումը։\n\n<a href="' + ADMIN + '/pipeline">Մանրամասներ ադմինում</a>';
  } else {
    key = wf + '|' + node + '|' + msg.slice(0, 80);
    text = '⚠️ <b>Ավտոմատացման սխալ</b>\n\nWorkflow՝ ' + esc(wf) + '\nՔայլ՝ ' + esc(node) + '\nՍխալ՝ <code>' + esc(msg.slice(0, 300)) + '</code>\n\nԵթե սխալը կրկնվում է, հայտարարությունները կարող են չհասնել Telegram։' + (url ? '\n<a href="' + url + '">Բացել n8n-ում</a>' : '');
  }
  if (sd.sent[key] && now - sd.sent[key] < 30 * 60 * 1000) continue;
  sd.sent[key] = now;
  out.push({ json: { text } });
}
return out;

const TOKEN = '__HEALTH_WEBHOOK_TOKEN__';
const out = [];
for (const it of $input.all()) {
  const hdr = it.json.headers || {};
  if (hdr['x-vip-health-token'] !== TOKEN) continue;
  const b = it.json.body || {};
  const state = String(b.state || 'unknown').replace(/[^a-z_]/gi, '').slice(0, 30);
  const text = state === 'open'
    ? '✅ <b>WhatsApp-ը նորից միացված է</b>\n\nԽմբի հայտարարությունները կրկին ընդունվում են։'
    : '🔴 <b>WhatsApp-ն անջատված է</b> (' + state + ')\n\nԽմբի հայտարարությունները հիմա չեն ստացվում։ Անհրաժեշտ է նորից միացնել WhatsApp-ը QR կոդով։' + (b.minutes ? '\nԱնջատված է արդեն ' + Number(b.minutes) + ' րոպե։' : '');
  out.push({ json: { text } });
}
return out;
